# -*- coding: utf-8 -*-
"""Armenian headwords and definitions for the Glossary. TERMS = {id: (headword, definition)}."""
TERMS = {
"abbot": ("Վանահայր (իգումեն)", "Վանքի առաջնորդը։"),
"aer": ("Աէր (մեծ սքող)", "Սքողներից ամենամեծը, որ ծածկում է և՛ սկիհամանը, և՛ բաժակը, և որով շարժում են Ընծաների վրա Հավատո հանգանակի ժամանակ։"),
"toll-houses": ("Օդային մաքսատներ", "Պատում հոգու մահվանից հետո անցած ճանապարհի մասին, ուր նա հաջորդական աստիճաններում քննվում է դևերի կողմից։ Հանդիպում է հայրաբանական, վարքագրական և պատարագային աղբյուրներում, և ուսուցանվել է բազում սուրբերի կողմից։"),
"akathist": ("Ակաթիստ", "Քսանչորս տնից բաղկացած շարական, որ երգվում է կանգնած, և անունն իսկ նշանակում է ոչ նստած։ Առաջինը Աստվածածնին է ուղղված. հետագա շատերը հետևում են նրա ձևին։"),
"akriveia": ("Ակրիվիա (խստություն)", "Ճշգրտություն. կանոնների խիստ կիրառումը, տնտեսության զույգը։"),
"vigil": ("Գիշերային հսկում", "Երեկոյան ժամերգությունը, առավոտյանը և առաջին ժամը միացած մեկ ժամերգության մեջ՝ կիրակիների և մեծ տոների նախօրեին։"),
"alleluiarion": ("Ալելուարիոն", "Ալելուն իր տողերով, որ երգվում է Առաքելականի և Ավետարանի միջև։"),
"ambo": ("Ամբիոն", "Սոլեայի ելուստը սուրբ դռների առջև, որտեղից կարդացվում է Ավետարանը և ասվում ամբիոնի ետևի աղոթքը։"),
"analavos": ("Անալավոս", "Մեծ սքեմի զգեստը, ասեղնագործված Խաչով, նիզակով, սպունգով և Չարչարանաց խոսքերով։"),
"analogion": ("Անալոգիոն (գրակալ)", "Թեք կանգնակ, որ պահում է սրբապատկեր կամ ժամերգության գիրք։"),
"anaphora": ("Անաֆորա", "Պատարագի կենտրոնական աղոթքը՝ ընծայումը, որ պարունակում է հաստատման խոսքերը և Հոգու կոչումը։"),
"antidoron": ("Անտիդորոն", "Պրոսֆորայի մնացորդը՝ օրհնված, բայց ոչ սրբագործված, որ բաժանվում է Պատարագի վերջում։ Անունը նշանակում է ընծայի փոխարեն. տրվում է բոլոր ներկաներին, նաև նրանց, ովքեր չեն հաղորդվել։"),
"antimension": ("Անտիմինս", "Եպիսկոպոսի ստորագրած կտավը, որ պարունակում է մասունքներ և փռվում սուրբ սեղանին։ Առանց դրա Պատարագ չի մատուցվում. այն եպիսկոպոսի թույլտվությունն է այդ սեղանի համար։"),
"apatheia": ("Անկրքություն (ապաթիա)", "Ոչ անզգայություն, այլ կրքերի բժշկություն, որպեսզի հոգու զորությունները ուղիղ շարժվեն դեպի Աստված։"),
"apostles-fast": ("Առաքելոց պահք", "Պահքը Ամենայն սուրբերի կիրակիին հաջորդող երկուշաբթիից մինչև սուրբ Պետրոս և Պողոս առաքյալների տոնը՝ հունիսի 29-ը։ Նրա տևողությունը փոխվում է Զատկի ամսաթվի հետ։"),
"archbishop": ("Արքեպիսկոպոս", "Բարձր աստիճանի եպիսկոպոս։ Հունական սովորույթում սովորաբար կանգնում է միտրոպոլիտից վեր, սլավոնականում՝ ներքև։"),
"archimandrite": ("Արքիմանդրիտ", "Բարձր աստիճանի վանական քահանա, հաճախ վանահայր կամ եպիսկոպոսության թեկնածու։"),
"archpriest": ("Ավագ քահանա", "Բարձր աստիճանի ծխական քահանա. պատվանուն է, ոչ թե առանձին աստիճան։"),
"artoklasia": ("Հացօրհնեք (արտոկլասիա)", "Հինգ հացի օրհնությունն ու բեկումը լիտիայի ժամանակ՝ ի հիշատակ հինգ հազարի կերակրման։"),
"asterisk": ("Աստղ (աստերիսկոս)", "Ծալովի աստղ, որ դրվում է սկիհամանի վրա, որպեսզի սքողը չդիպչի մասնիկներին. հիշեցնում է Բեթղեհեմի վերևի աստղը։"),
"autocephaly": ("Ինքնագլխություն (ավտոկեֆալիա)", "Այն Եկեղեցու վիճակը, որ ինքն է ընտրում իր առաջնորդին և ուրիշին ենթակա չէ՝ մնալով մյուսների հետ հաղորդության մեջ։"),
"autonomy": ("Ինքնավարություն", "Այն Եկեղեցու վիճակը, որ ինքն իրեն է կառավարում, բայց որի առաջնորդը հաստատվում է մայր Եկեղեցու կողմից։"),
"baptism": ("Մկրտություն", "Երեքկի ընկղմում Քրիստոսի մահվան և հարության մեջ, որով մարդ մտնում է Եկեղեցի։"),
"odes": ("Աստվածաշնչյան երգեր", "Գրքի ինը երգերը՝ Մովսեսի երգերից մինչև Աստվածածնի օրհներգը և Զաքարիայի աղոթքը, որոնց օրինակով հորինվում են կանոնի երգերը։"),
"bishop": ("Եպիսկոպոս", "Երեք մեծ աստիճաններից ամենաբարձրը, որ ունի քահանայության լրիվությունը, ձեռնադրում է հոգևորականներ և իր թեմի միասնության կենտրոնն է։"),
"bright-week": ("Լուսավոր շաբաթ", "Զատկին հաջորդող շաբաթը, որ պահվում է որպես տոնի մեկ անընդհատ օր՝ առանց պահքի և բաց սուրբ դռներով։"),
"canon-hymn": ("Կանոն (շարական)", "Առավոտյան ժամերգության երկար շարականը՝ ութ կամ ինը երգից, որոնցից յուրաքանչյուրը կապված է աստվածաշնչյան երգերից մեկին։"),
"canon-law": ("Կանոն (օրենք)", "Եկեղեցու կանոն, տրված ժողովի կամ հոր կողմից և ընդունված ողջ մարմնի կողմից։ Տարբերվում է առավոտյան ժամերգությանը երգվող կանոնից։"),
"catechumen": ("Երախա", "Նա, ով ուսուցանվում է հավատի մեջ՝ մկրտության պատրաստության համար. հին կարգով դուրս է գալիս հավատացյալների Պատարագից առաջ։"),
"catholicity": ("Ընդհանրականություն", "Եկեղեցու ամբողջականությունը. ոչ թե տարածում, այլ լիություն, քանզի յուրաքանչյուր տեղական Եկեղեցի, իր եպիսկոպոսի շուրջ հավաքված, ունի ամբողջը։ Ըստ ամբողջի արտահայտությունը փոխանցում է kath' holon-ը։"),
"censer": ("Բուրվառ", "Անոթ, որի մեջ խունկ է այրվում, սլավոնական և հունական շատ սովորույթներում՝ զանգակներով։"),
"chalice": ("Սուրբ Բաժակ", "Բաժակը, որ պարունակում է ընծայման գինին, իսկ սրբագործումից հետո՝ Քրիստոսի Արյունը։"),
"cherubic-hymn": ("Քերովբեական երգ", "Երգը, որ երգվում է Մեծ մուտքի ժամանակ, երբ հավատացյալները մի կողմ են դնում ամեն երկրային հոգս՝ ընդունելու ամենքի Թագավորին։"),
"chrismation": ("Դրոշմ (միռոնօծություն)", "Սուրբ միռոնով օծումը մկրտությունից անմիջապես հետո՝ Սուրբ Հոգու պարգևի կնիքը։"),
"churching": ("Եկեղեցի բերելը", "Մոր և մանկան բերումը եկեղեցի քառասուներորդ օրը՝ գոհության և օրհնության աղոթքներով։"),
"clean-monday": ("Մաքուր երկուշաբթի", "Մեծ Պահքի առաջին օրը՝ Ներման կիրակիից հետո։"),
"spoon": ("Հաղորդության գդալ", "Գդալը, որով հավատացյալները ընդունում են Մարմինը և Արյունը միասին։ Նրա հունարեն անունը նշանակում է ունելի՝ Եսայու տեսիլքում ունելիով վերցված ածուխի պատճառով։"),
"compline": ("Հանգստյան ժամերգություն (ապոդիպնոն)", "Ընթրիքից հետո, քնից առաջ կատարվող ժամերգությունը։ Փոքրը գործածվում է տարվա մեծ մասում, Մեծը պատկանում է Մեծ Պահքին և որոշ հսկումների։"),
"compunction": ("Զղջում (կատանիքսիս)", "Սրտի խոցումը, որ արցունք է բերում և փափկեցնում այն Աստծո առջև։"),
"confession": ("Խոստովանություն", "Ապաշխարության խորհուրդը, որում մեղքերը խոստովանվում են Աստծո առջև՝ քահանայի ներկայությամբ, և տրվում է թողություն։ Նրա հաճախականությունը զգալիորեն տարբերվում է ավանդույթների միջև։"),
"crowning": ("Պսակ (ամուսնություն)", "Ամուսնության խորհուրդը, այսպես կոչված նորապսակների գլխին դրվող պսակներից, որոնք նշանակում են և՛ թագավորություն, և՛ վկայություն։"),
"deacon": ("Սարկավագ", "Երրորդ աստիճանը, որ ծառայում է սեղանին, ասում մաղթանքները և միայնակ չի կարող կատարել խորհուրդները։"),
"dikirion": ("Երկճյուղ և եռաճյուղ աշտանակ", "Երկու և երեք ճյուղ ունեցող աշտանակները, որոնցով եպիսկոպոսն օրհնում է՝ նշանակելով Քրիստոսի երկու բնությունները և Երրորդության երեք Անձերը։"),
"diptychs": ("Դիպտիքոններ", "Պատարագին հիշատակվող ողջերի և ննջեցյալների ցուցակները, իսկ առաջնորդների միջև՝ պատվի և հաղորդության կարգը։"),
"diskos": ("Սկիհաման (դիսկոս)", "Ոտք ունեցող ափսե, որի վրա դրվում են Գառը և հիշատակի մասնիկները։"),
"dispassion": ("Անկրքություն (անգլ. dispassion)", "Ապաթիա բառի անգլերեն թարգմանությունը. տես այդ հոդվածը։"),
"divine-liturgy": ("Սուրբ Պատարագ", "Եկեղեցու հաղորդության ժամերգությունը, որում հացն ու գինին ընծայվում են և դառնում Քրիստոսի Մարմինն ու Արյունը։ Առավել հաճախ մատուցվում է սուրբ Հովհան Ոսկեբերանի կարգով։"),
"dormition-fast": ("Վերափոխման պահք", "Օգոստոսի 1-ից 14-ը պահքը՝ Աստվածածնի Վերափոխումից առաջ։"),
"economia": ("Տնտեսություն (իկոնոմիա)", "Հովվական խոհեմությունը, որով կանոնի խիստ կիրառումը մեղմվում է հոգիների փրկության համար. ակրիվիայի զույգը։"),
"ecumenical-council": ("Տիեզերական ժողով", "Ժողով, որի սահմանումներն ընդունել է ողջ Եկեղեցին։ Ուղղափառ Եկեղեցին ընդունում է յոթը՝ 325 թ. Նիկիայից մինչև 787 թ. Երկրորդ Նիկիա։"),
"elder": ("Ծեր (ստարեց, գերոնդա)", "Զանազանության շնորհ ունեցող վանական, որին ուրիշներն իրենց խորհուրդներն են բացում և որից առաջնորդություն ստանում։"),
"epigonation": ("Էպիգոնատիոն", "Աջ ծնկի մոտ կախված կոշտ շեղանկյուն կտավը, որ տրվում է որպես պատվանշան. նշանակում է Հոգու սուրը։"),
"epiklesis": ("Հոգու կոչում (էպիկլեզ)", "Սուրբ Հոգու կանչումը Ընծաների և հավաքվածների վրա, որի ժամանակ Ուղղափառ Եկեղեցին հասկանում է, որ սրբագործումը կատարվում է։"),
"epimanikia": ("Բազպաններ (էպիմանիկիա)", "Հոգևորականների կրած բազպանները, որոնք սեղմում են թևքերը և նշանակում Քրիստոսի կապանքները։"),
"epitaphios": ("Պատանք (էպիտաֆիոս)", "Ասեղնագործ կտավ՝ գերեզման դրված Քրիստոսի պատկերով, որ Ավագ ուրբաթ օրը թափորով տարվում է։"),
"epitimia": ("Ապաշխարանք (էպիտիմիա)", "Խոստովանության ժամանակ տրվող կանոն՝ որպես դեղ, ոչ որպես պատիժ. գետնախոնարհություններ, ողորմություն կամ որոշ ժամանակով հաղորդությունից ձեռնպահ մնալ։"),
"epitrachelion": ("Փորուրար (էպիտրաքիլ)", "Քահանայի փորուրարը, որ կրվում է պարանոցին։ Առանց դրա ոչ մի քահանայական ժամերգություն չի կատարվում։"),
"essence-energies": ("Էություն և զորություններ", "Սուրբ Գրիգոր Պալամասի բացատրած տարբերությունը Աստծո անճանաչելի էության և նրա անեղ զորությունների միջև, որոնցով նա ճշմարտապես հաղորդակցվում է։"),
"euchologion": ("Մաշտոց (էվքոլոգիոն)", "Քահանայի ժամերգության գիրքը, որ պարունակում է Պատարագի աղոթքները, խորհուրդները և առիթային կարգերը։"),
"fast-free": ("Անպահք շաբաթ", "Շաբաթ, որում չորեքշաբթի և ուրբաթ օրերի պահքը վերացվում է, ինչպես Լուսավոր շաբաթը և Պենտեկոստեին հաջորդող շաբաթը։"),
"forefeast": ("Նախատոն և հետտոն", "Մեծ տոնից առաջ պատրաստության օրերը և դրանից հետո շարունակության օրերը։"),
"forgiveness-vespers": ("Ներման երեկոյան ժամերգություն", "Մեծ Պահքի սկսվելուց նախորդ երեկոյան ժամերգությունը, որին հավատացյալները միմյանցից ներողություն են խնդրում։"),
"glorification": ("Սրբադասում", "Եկեղեցու ճանաչումն այն մասին, որ մարդը սուրբերի շարքում է, որով պաշտոնականացվում է հավատացյալների մեջ արդեն ծագած պատվումը։"),
"theophany-water": ("Ջրօրհնեք մեծ", "Ջրի օրհնությունը Աստվածահայտնության տոնին. պահվում է ողջ տարին և ըստ պետքի ըմպվում։"),
"doxology": ("Մեծ փառաբանություն", "Փառք ի բարձունս Աստծո, որ երգվում է առավոտյան ժամերգության վերջին մասում կիրակիներին և տոներին։"),
"great-entrance": ("Մեծ մուտք", "Թափորը, որ բերում է պատրաստված Ընծաները ընծայման սեղանից սուրբ սեղան՝ Քերովբեական երգի ընթացքում։"),
"great-feasts": ("Մեծ տոներ", "Տարվա տասներկու գլխավոր տոները՝ Զատկի հետ միասին, որ նրանցից վեր է որպես տոների տոն։"),
"great-lent": ("Մեծ Պահք", "Քառասնօրյա պահքը Ավագ շաբաթից և Զատկից առաջ, որ սկսվում է Մաքուր երկուշաբթի։"),
"great-schema": ("Մեծ սքեմ", "Վանական կարգի ամենաբարձր աստիճանը՝ անալավոսով և ուժեղացված աղոթքի ու մեկուսացման կանոնով։"),
"hesychasm": ("Հեսիխազմ", "Ներքին լռության և անդադար աղոթքի ավանդույթը, պաշտպանված սուրբ Գրիգոր Պալամասի կողմից և հաստատված տասնչորսերորդ դարի ժողովների կողմից։"),
"hierodeacon": ("Վանական սարկավագ", "Սարկավագ ձեռնադրված վանական։"),
"hieromonk": ("Վանական քահանա", "Քահանա ձեռնադրված վանական։"),
"myron": ("Սուրբ Միռոն", "Անուշահոտ յուղը, որ սրբագործվում է պատրիարքի կամ սինոդի կողմից և գործածվում դրոշմի ժամանակ։"),
"altar-table": ("Սուրբ սեղան (խորան)", "Սեղանը սրբարանի կենտրոնում, որի վրա մատուցվում է Պատարագը. այն պարունակում է մասունքներ։"),
"unction": ("Սուրբ յուղով օծում", "Հիվանդների օծումը օրհնված յուղով՝ հոգու և մարմնի բժշկության համար, կատարվում է մի քանի քահանաների կողմից, ուր հնարավոր է։"),
"holy-week": ("Ավագ շաբաթ", "Շաբաթը Ծաղկազարդից մինչև Ավագ շաբաթ օրը՝ Մեծ Պահքից հետո և Զատկից առաջ։"),
"horologion": ("Ժամագիրք", "Ժամերի գիրքը, որ պարունակում է ժամերգությունների օրական շրջանի անփոփոխ մասերը։"),
"hypostasis": ("Անձ (հիպոստաս)", "Անձ, տարբեր բնությունից կամ էությունից։ Երրորդությունը երեք անձ է մեկ էության մեջ. Քրիստոսը մեկ անձ է երկու բնության մեջ։"),
"iconography": ("Սրբապատկեր (իկոն)", "Քրիստոսի, Աստվածածնի կամ սուրբերի գրված պատկերը, պատվվում է, քանզի պատիվն անցնում է նախատիպին։ Պաշտպանվել է Յոթերորդ Տիեզերական ժողովում։"),
"iconostasis": ("Սրբապատկերների պատ (իկոնոստաս)", "Սրբապատկերների պատը տաճարի և սրբարանի միջև, կենտրոնում սուրբ դռներով և սրբապատկերների հաստատուն կարգով։"),
"incarnation": ("Մարմնացում", "Հավերժական Բանի կողմից մարդկային բնության ընդունումը՝ ճշմարիտ Աստված և ճշմարիտ մարդ մեկ անձի մեջ։"),
"incense": ("Խունկ", "Այրվում է ժամերգություններին՝ նշանակելով Աստծո առջև բարձրացող աղոթքը։"),
"incorrupt": ("Անապականություն", "Սուրբի մարմնի պահպանումն ապականությունից, ընդունվում է որպես սրբության նշան, թեև սրբադասման համար չի պահանջվում։"),
"indiction": ("Ինդիկտիոն", "Եկեղեցական տարվա սկիզբը սեպտեմբերի 1-ին։"),
"irmos": ("Իրմոս", "Կանոնի յուրաքանչյուր երգի առաջին տաղը, որ սահմանում է նրա եղանակն ու չափը և կապում աստվածաշնչյան երգին։"),
"jesus-prayer": ("Հիսուսյան աղոթք", "Տեր Հիսուս Քրիստոս, Որդի Աստծո, ողորմիր ինձ՝ մեղավորիս. կրկնվում է որպես անդադար աղոթքի հիմք։"),
"julian-calendar": ("Հուլյան և վերանայված հուլյան օրացույցներ", "Հին հուլյանը, որ մի քանի Եկեղեցիներ պահում են ողջ տարին, և վերանայված հուլյանը, որ անշարժ տոներում հետևում է գրիգորյանին՝ պահելով հուլյան Զատկահաշիվը։"),
"katavasia": ("Կատավասիա", "Երգի վերջում կրկնվող իրմոսը. այսպես կոչված, քանի որ դասերն իջնում էին իրենց տեղերից՝ այն միասին երգելու համար։"),
"kathisma": ("Կաթիսմա", "Սաղմոսարանի քսան բաժիններից մեկը. նաև նստելու շարական, որ երգվում է դրանից հետո և որի ընթացքում թույլատրվում է նստել։"),
"kenosis": ("Կենոսիս (ինքնաունայնացում)", "Որդու ինքնաունայնացումը Մարմնացման մեջ, որի մասին խոսում է Փիլիպպեցիների 2-րդ գլուխը։"),
"klobuk": ("Կլոբուկ", "Վանականի գլխարկը՝ գլանաձև գդակ վարագույրով։"),
"koliva": ("Կոլիվա", "Մեղրով և պտուղներով եփած ցորեն, որ օրհնվում է հոգեհանգստյան ժամանակ, ըստ Տիրոջ խոսքի, թե հատիկը պետք է մեռնի՝ պտուղ տալու համար։"),
"kontakion": ("Կոնդակ", "Երկրորդ կարճ շարականը, որ ամփոփում է տոնը կամ սուրբը։ Ի սկզբանե դա երկար բանաստեղծական քարոզ էր՝ բազում տներով, որից պահպանված կոնդակն առաջինն է։"),
"lance": ("Նիզակ (փոքր դանակ)", "Նիզակաձև փոքր դանակը, որ գործածվում է ընծայման ժամանակ՝ Գառը և մասնիկները կտրելու համար. հիշեցնում է Քրիստոսի կողը խոցած նիզակը։"),
"leavetaking": ("Տոնի արձակում (ապոդոսիս)", "Հետտոնի վերջին օրը, որ պահվում է հենց տոնի շարականների մեծ մասով։"),
"little-entrance": ("Փոքր մուտք", "Ավետարանի գրքով թափորը Պատարագի սկզբին մոտ։"),
"liturgy-of-basil": ("Սուրբ Բարսեղի Պատարագ", "Սուրբ Պատարագի ավելի երկար ձևը՝ իր անաֆորայով, մատուցվում է տարին տասն անգամ. Մեծ Պահքի կիրակիներին բացի Ծաղկազարդից, Ավագ հինգշաբթի և Ավագ շաբաթ, Ծննդյան և Աստվածահայտնության նախօրեին, և սուրբ Բարսեղի տոնին՝ հունվարի 1-ին։"),
"presanctified": ("Նախասրբագործված Ընծաների Պատարագ", "Երեկոյան ժամերգություն՝ նախորդ կիրակիի Պատարագին սրբագործված Ընծաներով հաղորդությամբ, մատուցվում է Մեծ Պահքի աշխատանքային օրերին, երբ լիակատար Պատարագ չի մատուցվում։"),
"litya": ("Լիտիա", "Հսկման ժամանակ թափորը և բարեխոսությունը, որի ընթացքում օրհնվում են հացը, ցորենը, գինին և յուղը։"),
"logismoi": ("Խորհուրդներ (լոգիսմոի)", "Միտքը հարձակվող խորհուրդներ կամ թելադրանքներ, որ պետք է զանազանել և մերժել, նախքան դրանք համաձայնություն դառնան։"),
"mandyas": ("Մանդիաս", "Ամբողջական վերարկուն, որ եպիսկոպոսը կրում է թափորի ժամանակ, իսկ ավելի պարզ ձևով՝ մեծ սքեմի վանականները։"),
"menaion": ("Մենեոն (Տոնացույց)", "Անշարժ տոների շարականների տասներկու հատորները՝ տարվա յուրաքանչյուր ամսվա համար մեկ։"),
"menologion": ("Մենոլոգիոն", "Սուրբերի վարքերի ժողովածու՝ դասավորված ամսվա օրերով։"),
"metanoia": ("Մետանոիա (ապաշխարություն)", "Բառացի՝ մտքի փոփոխություն, ողջ մարդու դարձը դեպի Աստված։ Նույն բառը կոչում է նաև գետնախոնարհությունը։"),
"metropolitan": ("Միտրոպոլիտ", "Գլխավոր քաղաքի եպիսկոպոս, որ իր գավառի եպիսկոպոսներից վեր է։ Գործածությունը տարբեր է հունական և սլավոնական Եկեղեցիներում։"),
"moleben": ("Մոլեբեն (խնդրանքի կարգ)", "Խնդրանքի ժամերգություն Քրիստոսին, Աստվածածնին կամ սուրբին՝ հաստատուն շրջանից դուրս, որոշակի կարիքի կամ գոհության համար։"),
"monk": ("Վանական", "Վանական կյանքի համար կտրված մազերով, հնազանդության, ողջախոհության և աղքատության ուխտերի ներքո։"),
"mystery": ("Խորհուրդ (խորհրդակատարություն)", "Եկեղեցու գործողություն, որում շնորհը տրվում է տեսանելի միջոցներով։ Ուղղափառ Եկեղեցին երբեք դավանաբանորեն չի սահմանել դրանց թիվը, թեև սովորաբար յոթն են թվարկվում։"),
"nabedrennik": ("Նաբեդրեննիկ", "Ուղղանկյուն կտավ՝ կրվող ազդրի մոտ, սլավոնական Եկեղեցիների պատվանշան, որ հունականում համարժեք չունի։"),
"narthex": ("Գավիթ (նարթեքս)", "Եկեղեցու մուտքի սրահը, ուր նախկինում կանգնում էին երախաներն ու ապաշխարողները, և ուր սկսվում են մի քանի ժամերգություններ։"),
"nativity-fast": ("Ծննդյան պահք", "Քառասնօրյա պահքը նոյեմբերի 15-ից՝ Քրիստոսի Ծննդից առաջ։"),
"nave": ("Տաճարի մարմին", "Եկեղեցու մարմինը, ուր կանգնում են հավատացյալները։"),
"nepsis": ("Զգաստություն (նեփսիս)", "Սթափ ուշադրություն խորհուրդներին, հենց որ դրանք ծագում են, որպեսզի դիմավորվեն նախքան արմատ գցելը։"),
"novice": ("Փորձառու (նորընծա)", "Նա, ով վանքում ապրում է փորձության մեջ՝ նախքան մազերի կտրումը։"),
"obedience": ("Հնազանդություն", "Սեփական կամքի կտրումը ծերի կամ կանոնի առջև. նաև վանականին տրված որոշակի հանձնարարությունը։"),
"octoechos": ("Ութձայնյան (օկտոիխոս)", "Ութ ձայների գիրքը, որ կարգավորում է սովորական շաբաթների հարության շարականներն ութշաբաթյա շրջանում։"),
"oikos": ("Իկոս", "Կոնդակին հաջորդող տունը, որ ծավալում է նրա նյութը։"),
"omophorion": ("Ուրար (օմոֆոր)", "Եպիսկոպոսի ուսերին կրվող լայն ժապավենը, որ նշանակում է Բարի Հովվի կրած մոլորված ոչխարը։ Այն նշում է նրա պաշտոնը։"),
"orarion": ("Սարկավագի ուրար", "Երկար նեղ ժապավենը, որ սարկավագը կրում է ձախ ուսին և բարձրացնում մաղթանքների ժամանակ։"),
"orthros": ("Առավոտյան ժամերգություն (օրթրոս)", "Առավոտյան ժամերգությունը, ամենաերկարն օրական շրջանում, պարունակում է վեց սաղմոսները, կանոնը, և գործածությունների մեծ մասում՝ Մեծ փառաբանությունը։"),
"panagia": ("Պանագիա", "Աստվածածնի սրբապատկերով մեդալիոնը, որ եպիսկոպոսը կրում է կրծքին։"),
"panikhida": ("Հոգեհանգիստ (պանիխիդա)", "Ննջեցյալների հիշատակի ժամերգությունը, կատարվում է երրորդ, իններորդ և քառասուներորդ օրը, տարելիցներին և հոգեհանգստյան շաբաթներին։"),
"paraklesis": ("Պարակլիսիս", "Աստվածածնին ուղղված աղերսական կանոնը։ Փոքրը երգվում է Վերափոխման պահքի ընթացքում, Մեծը պատկանում է հատուկ նեղության ժամանակներին։"),
"pascha": ("Զատիկ (Պասխա)", "Քրիստոսի Հարությունը, տոների տոնը, որից հաշվվում է շարժական շրջանը։"),
"paschalion": ("Զատկահաշիվ", "Զատկի ամսաթվի հաշվարկը և աղյուսակը, որով այն գտնվում է։"),
"passions": ("Կրքեր", "Հոգու անկարգ շարժումները. ոչ թե բնական ցանկություններն իրենք, այլ դրանց ապականումը ստրկության։"),
"patriarch": ("Պատրիարք", "Պատրիարքական աստիճանի ինքնագլուխ Եկեղեցու առաջնորդը։"),
"pentecostarion": ("Պենտեկոստարիոն", "Գիրքը և ժամանակաշրջանը Զատկից մինչև Ամենայն սուրբերի կիրակին։"),
"penthos": ("Սուգ (պենթոս)", "Մեղքի համար սուգը, Աստծո կամքով տրտմությունը, որ ապաշխարություն է գործում, հաճախ արցունքների հետ միասին։"),
"phelonion": ("Շուրջառ (ֆելոնիոն)", "Քահանայի լայն, անթև վերին զգեստը Պատարագի ժամանակ։"),
"philokalia": ("Ֆիլոկալիա", "Ճգնական և խորհրդածական տեքստերի ժողովածուն չորրորդից տասնհինգերորդ դար, կազմված սուրբ Նիկոդիմոսի և Կորնթոսի սուրբ Մակարիոսի կողմից, հրատարակված 1782 թ.։"),
"phronema": ("Ֆրոնիմա (Եկեղեցու միտք)", "Եկեղեցու միտքը կամ մտածելակերպը, որ ձևավորվում է նրա մեջ ապրելով, ոչ միայն ուսումնասիրությամբ։"),
"phyletism": ("Ֆիլետիզմ", "Եկեղեցու շփոթումն ազգի հետ, դատապարտված որպես հերձված Կոստանդնուպոլսի ժողովի կողմից 1872 թ.։"),
"polyeleos": ("Պոլիելեոս", "134-րդ և 135-րդ սաղմոսները, որ երգվում են տոնական առավոտյան ժամերգությանը, այսպես կոչված իրենց կրկներգից՝ քանզի հավիտյան է նրա ողորմությունը։"),
"departed-prayers": ("Աղոթք ննջեցյալների համար", "Եկեղեցու սովորությունը՝ աղոթել մահացածների համար, արտահայտված հոգեհանգստի, հոգեհանգստյան շաբաթների և ընծայման հիշատակությունների մեջ։"),
"prayer-of-heart": ("Սրտի աղոթք", "Հիսուսյան աղոթքը, որ մտքից իջել է սիրտ և դարձել անդադար։"),
"prayer-rope": ("Աղոթքի պարան", "Հանգույցներով բրդյա պարան՝ Հիսուսյան աղոթքը հաշվելու համար, սովորաբար երեսուներեք, հիսուն կամ հարյուր հանգույցով։"),
"priest": ("Քահանա (երեց)", "Երկրորդ աստիճանը, ձեռնադրված եպիսկոպոսի կողմից՝ ծխում Պատարագ և խորհուրդներ կատարելու համար։"),
"prokeimenon": ("Պրոկիմենոն", "Տող, սովորաբար սաղմոսներից, որ երգվում է Գրքի ընթերցումից առաջ։"),
"prosoche": ("Ուշադրություն (պրոսոխի)", "Ուշադրություն. մտքի պահպանումն աղոթքի մեջ։"),
"prosphora": ("Պրոսֆորա", "Թթխմորով հացը, որ ընծայվում է Պատարագի համար, կնքված կնիքով, որից կտրվում է Գառը։"),
"prostration": ("Գետնախոնարհություն", "Մինչև գետին խոնարհումը՝ ապաշխարության և երկրպագության մեջ։ Գետնախոնարհություն չի արվում կիրակիներին և զատկական շրջանում։"),
"prothesis": ("Ընծայում (պրոսկոմիդիա)", "Հացի և գինու պատրաստումը Պատարագից առաջ՝ ընծայման սեղանին, որի ընթացքում մասնիկներ են կտրվում ողջերի և ննջեցյալների համար։"),
"psalter": ("Սաղմոսարան", "150 սաղմոսները՝ բաժանված քսան կաթիսմայի ժամերգություններում ընթերցելու համար, ինը աստվածաշնչյան երգերի հետ միասին։"),
"rassophore": ("Ռասոֆոր", "Վանական կարգի առաջին աստիճանը՝ փիլոն կրողը, առանց լիակատար ուխտերի։"),
"reader": ("Դպիր (ընթերցող)", "Փոքր աստիճան, առանձնացված Առաքելականը և սահմանված տեքստերն ընթերցելու համար։"),
"relics": ("Մասունքներ", "Սուրբերի մարմնական մնացորդները, պատվվում են, քանզի մարմինը Սուրբ Հոգու տաճար է։ Մասունքները կնքվում են անտիմինսի և սեղանի մեջ։"),
"royal-doors": ("Սուրբ դռներ", "Սրբապատկերների պատի կենտրոնական դռները, որոնցով անցնում են միայն հոգևորականները և որոնցով բերվում են Ընծաները։"),
"sakkos": ("Սակկոս", "Եպիսկոպոսի վերին զգեստը, որ հիերարխների համար փոխարինեց շուրջառին։"),
"salutations": ("Ողջույններ (ակաթիստի ուրբաթներ)", "Մեծ Պահքի ուրբաթ երեկոյան ժամերգությունները, որոնց Աստվածածնի Ակաթիստը երգվում է մասերով։"),
"sanctuary": ("Սրբարան (խորան)", "Սրբապատկերների պատի ետևի տարածքը՝ սուրբ սեղանով, ընծայման սեղանով և բարձր աթոռով։"),
"solea": ("Սոլեա", "Բարձրացված անցուղին սրբապատկերների պատի առջև, որտեղից հավատացյալները հաղորդվում են։"),
"soul-saturday": ("Հոգեհանգստյան շաբաթ", "Շաբաթ օրերը, որոնք սահմանված են բոլոր ննջեցյալների հիշատակի համար։"),
"spiritual-father": ("Հոգևոր հայր", "Քահանան կամ ծերը, որ լսում է խոստովանությունը և առաջնորդում մարդու կյանքը Քրիստոսի մեջ։"),
"stavrophore": ("Ստավրոֆոր (Փոքր սքեմ)", "Վանական կարգի երկրորդ աստիճանը՝ խաչակիրը, որի ժամանակ տրվում են լիակատար ուխտերը։"),
"stavrotheotokion": ("Խաչի աստվածածնական", "Աստվածածնական Խաչի մոտ կանգնած Աստվածամոր մասին, գործածվում է չորեքշաբթի և ուրբաթ օրերին։"),
"sticharion": ("Շապիկ (ստիխարիոն)", "Երկար պատմուճանը, որ կրում են հոգևորականների բոլոր աստիճանները, ինչպես նաև դպիրներն ու սպասավորները։"),
"sticheron": ("Ստիխարան", "Շարական, որ երգվում է սաղմոսի տողերի միջև, հատկապես երեկոյան և առավոտյան ժամերգություններին։"),
"subdeacon": ("Կիսասարկավագ", "Փոքր աստիճան, որ սպասարկում է եպիսկոպոսին և հոգ տանում անոթների մասին։"),
"synaxarion": ("Սինաքսարիոն (Հայսմավուրք)", "Օրվա համար սահմանված սուրբերի և տոների պատմությունը, որ ընթերցվում է առավոտյան ժամերգությանը. նաև այն գիրքը, որ դրանք հավաքում է։"),
"tabernacle": ("Խորհրդանոց", "Անոթը սուրբ սեղանի վրա, որում պահվում են նախասրբագործված Ընծաները հիվանդների համար և Նախասրբագործված Ընծաների Պատարագի համար։"),
"hours": ("Ժամեր", "Օրվա չորս կարճ ժամերգությունները՝ առաջին, երրորդ, վեցերորդ և իններորդ, հաշվված արևածագից, յուրաքանչյուրն իր սաղմոսներով և իր նյութով։"),
"lamb": ("Գառ", "Առաջին պրոսֆորայից կտրված քառակուսի մասը, որ սրբագործվում է և դառնում Քրիստոսի Մարմինը։"),
"rudder": ("Ղեկ (Պիդալիոն)", "Եկեղեցու կանոնների գլխավոր հունական ժողովածուն՝ մեկնությամբ, կազմված Սուրբ Լեռան սուրբ Նիկոդիմոսի և սուրբ Ագապիոսի կողմից, հրատարակված 1800 թ.։"),
"theosis": ("Աստվածացում (թեոսիս)", "Մարդկային անձի մասնակցությունն աստվածային կյանքին շնորհով, այն նպատակը, որի համար ստեղծվեց մարդը։ Շնորհով և ոչ բնությամբ։"),
"theotokion": ("Աստվածածնական", "Շարական Աստվածամորը, դրված շարականների խմբի վերջում։"),
"theotokos": ("Աստվածածին", "Աստվածածին, կույս Մարիամի տիտղոսը, հաստատված Եփեսոսում 431 թ.։ Այն պահպանում է այն ճշմարտությունը, որ նրանից ծնվածն Աստված է։"),
"tone": ("Ձայն (իխոս)", "Ութ երաժշտական եղանակներից մեկը, որով երգվում են շարականները, փոխվում է շաբաթից շաբաթ ըստ Ութձայնյանի։"),
"triodion": ("Տրիոդիոն", "Գիրքը և ժամանակաշրջանը Մեծ Պահքից առաջ և նրա ընթացքում գտնվող շաբաթների, մինչև Ավագ շաբաթ։ Այսպես կոչված իր եռերգյա կանոնների պատճառով։"),
"trisagion": ("Երեքսրբյան", "Սուրբ Աստված, սուրբ և հզոր, սուրբ և անմահ, ողորմիր մեզ. երգվում է երեք անգամ։ Նաև այն կարճ աղոթքների շարքի անունն է, որով սկսվում են ժամերգությունների մեծ մասը։"),
"troparion": ("Տրոպար", "Տոնի կամ սուրբի գլխավոր կարճ շարականը, որ ներկայացնում է նրա նյութը։ Կոչվում է նաև ապոլիտիկիոն, երբ երգվում է արձակման ժամանակ։"),
"typikon": ("Տիպիկոն", "Կանոնակարգի գիրքը, որ ցույց է տալիս, թե ինչպես են պահվում ժամերգություններն ու պահքերը և ինչպես են միացվում շրջանները, երբ դրանք համընկնում են։"),
"veneration": ("Պատվում և երկրպագություն", "Երկրորդ Նիկիայում հաստատված տարբերությունը. պաշտամունքային երկրպագությունը պատկանում է միայն Աստծուն, իսկ պատվումը մատուցվում է սրբապատկերներին, մասունքներին և սուրբերին։"),
"vespers": ("Երեկոյան ժամերգություն", "Երեկոյան ժամերգությունը, որով սկսվում է պատարագային օրը։ Բացվում է 103-րդ սաղմոսով և ճրագների վառելով։"),
"xerophagy": ("Չոր կերակուր (քսերոֆագիա)", "Սովորական պահքի ամենախիստ աստիճանը՝ առանց յուղի և գինու, պահվում է Մեծ Պահքի աշխատանքային օրերին։"),
"zeon": ("Ջերմություն (զեոն)", "Տաք ջուրը, որ լցվում է բաժակի մեջ հաղորդությունից առաջ՝ նշանակելով Սուրբ Հոգու ջերմությունը և այն, որ ընդունվող Մարմինը կենդանի է։"),
"zone": ("Գոտի", "Գոտին, որ քահանան կամ եպիսկոպոսը կրում է շապիկի և փորուրարի վրա։"),
}
